#define GFS_CURVED_TRANSFER_LIBRARY
#include "test_curved_transfer_v1.cpp"
#include "material_curved_topology.h"
struct TopologyRow {uint64_t triangle=0,evaluations=0,leaves=0,stable=0,polynomials=0,root_panels=0;R mass_bound=0,K_bound=0,mass_allow=0,K_allow=0;int deepest=0,complete=0;};
static TopologyRow certify_topology(size_t it,const curved::Packet &p,const std::vector<curved_partition::Site> &site,const std::vector<R> &weight,std::vector<curved_topology::Panel> &leaf){
    const auto &r=p.record[it];curved_bounds::Tri tri;for(int a=0;a<3;a++)for(int k=0;k<2;k++)tri[a][k]=r.triangle.geometry.x[a][k];auto bounds=positive_source_bounds(r,tri,p.parameters[3]);need(bounds.J.lo>0,"positive interval J before topology guard");TopologyRow row={};row.triangle=it;R Ulower=p.parameters[2]*r.triangle.geometry.area*powl(bounds.J.hi,1-p.parameters[1])/(p.parameters[1]-1);row.K_allow=1e-9L*Ulower;row.mass_allow=1e-12L*p.parameters[6]*r.triangle.geometry.area;auto cuts=radial_cuts(r);
    auto compiled=curved_compiled::compile(r,p.parameters[3]);auto evaluate=[&](R low,R high,int depth){auto panel=curved_topology::panel(r,p,low,high,depth,site,weight,bounds,&compiled);if(panel.stable)panel.mass_bound=panel.K_bound=0;row.evaluations++;row.polynomials+=panel.polynomials;row.root_panels+=panel.root_panels;row.deepest=std::max(row.deepest,depth);return panel;};
    for(size_t j=0;j+1<cuts.size();j++)leaf.push_back(evaluate(cuts[j],cuts[j+1],0));
    while(true){
        row.mass_bound=row.K_bound=0;int selected=-1;R worst=0;for(size_t j=0;j<leaf.size();j++){const auto &v=leaf[j];row.mass_bound+=v.mass_bound;row.K_bound+=v.K_bound;R priority=std::max(v.mass_bound/row.mass_allow,v.K_bound/row.K_allow);if(v.depth<32 && priority>worst){worst=priority;selected=j;}}
        if(row.mass_bound<=row.mass_allow && row.K_bound<=row.K_allow){row.complete=1;break;}if(selected<0 || row.evaluations+2>256)break;
        auto parent=leaf[selected];leaf.erase(leaf.begin()+selected);R mid=(parent.low+parent.high)/2;need(mid>parent.low && mid<parent.high,"strict radial event subdivision");leaf.push_back(evaluate(parent.low,mid,parent.depth+1));leaf.push_back(evaluate(mid,parent.high,parent.depth+1));
    }
    std::sort(leaf.begin(),leaf.end(),[](const auto &a,const auto &b){return a.low<b.low;});row.leaves=leaf.size();for(const auto &v:leaf)row.stable+=v.stable;return row;
}
#ifndef GFS_CURVED_TOPOLOGY_LIBRARY
int main(int argc,char **argv){
    int provided;MPI_Init_thread(&argc,&argv,MPI_THREAD_FUNNELED,&provided);active_mpi=true;need(provided>=MPI_THREAD_FUNNELED,"MPI FUNNELED");int rank,ranks;MPI_Comm_rank(MPI_COMM_WORLD,&rank);MPI_Comm_size(MPI_COMM_WORLD,&ranks);need(argc==4,"actual curved packet, advected sites, new output");auto p=curved::read(argv[1]);auto site=curved_partition::read_sites(argv[2]);std::vector<R> weight(site.size(),0);std::vector<TopologyRow> row(p.record.size());std::vector<std::vector<curved_topology::Panel>> leaves(p.record.size());auto started=std::chrono::steady_clock::now();
    #pragma omp parallel for schedule(dynamic,1)
    for(int it=0;it<(int)p.record.size();it++)if(it%ranks==rank)row[it]=certify_topology(it,p,site,weight,leaves[it]);
    char filename[1024];snprintf(filename,sizeof(filename),"%s/radial_panels_rank%d.csv",argv[3],rank);FILE *f=fopen(filename,"w");need(f,"retained complete/uncertain radial panels");fprintf(f,"triangle,low,high,depth,stable,mass_bound,K_bound\n");for(size_t it=0;it<leaves.size();it++)for(const auto &v:leaves[it])fprintf(f,"%zu,%.21Lg,%.21Lg,%d,%d,%.21Lg,%.21Lg\n",it,v.low,v.high,v.depth,v.stable,v.mass_bound,v.K_bound);fclose(f);
    std::vector<TopologyRow> gathered(rank==0?row.size()*ranks:0);MPI_Gather(row.data(),row.size()*sizeof(TopologyRow),MPI_BYTE,gathered.data(),row.size()*sizeof(TopologyRow),MPI_BYTE,0,MPI_COMM_WORLD);
    if(rank==0){
        for(size_t it=0;it<row.size();it++)row[it]=gathered[(it%ranks)*row.size()+it];std::string path=std::string(argv[3])+"/topology_rows.csv";f=fopen(path.c_str(),"w");need(f,"per-triangle event bound ledger");fprintf(f,"triangle,cell,evaluations,leaves,stable,polynomials,root_panels,mass_bound,K_bound,mass_allow,K_allow,deepest,complete\n");uint64_t evaluations=0,all_leaves=0,stable=0,poly=0,roots=0,passed=0;R sumM=0,sumK=0,maxMratio=0,maxKratio=0;int deepest=0;
        for(const auto &r:row){fprintf(f,"%llu,%llu,%llu,%llu,%llu,%llu,%llu,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%d,%d\n",(unsigned long long)r.triangle,(unsigned long long)p.record[r.triangle].cell,(unsigned long long)r.evaluations,(unsigned long long)r.leaves,(unsigned long long)r.stable,(unsigned long long)r.polynomials,(unsigned long long)r.root_panels,r.mass_bound,r.K_bound,r.mass_allow,r.K_allow,r.deepest,r.complete);evaluations+=r.evaluations;all_leaves+=r.leaves;stable+=r.stable;poly+=r.polynomials;roots+=r.root_panels;passed+=r.complete;sumM+=r.mass_bound;sumK+=r.K_bound;maxMratio=std::max(maxMratio,r.mass_bound/r.mass_allow);maxKratio=std::max(maxKratio,r.K_bound/r.K_allow);deepest=std::max(deepest,r.deepest);}fclose(f);double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count();
        printf("{\"scope\":\"interval-radius root-branch and ordering audit of actual W0 curved map; unresolved radial events retained with mass and absolute K bounds; engineering native rounding envelope included; not quadrature convergence, weight solve, exact C0 or time evolution\",\"ranks\":%d,\"OMP_threads\":%d,\"triangles\":%zu,\"complete_triangles\":%llu,\"evaluation_cap_per_triangle\":256,\"depth_cap\":32,\"evaluations\":%llu,\"leaves\":%llu,\"stable_leaves\":%llu,\"polynomials\":%llu,\"root_panels\":%llu,\"deepest\":%d,\"event_mass_bound\":%.17Lg,\"event_K_bound\":%.17Lg,\"max_mass_bound_over_allowance\":%.17Lg,\"max_K_bound_over_allowance\":%.17Lg,\"all_event_bounds_pass\":%s,\"seconds\":%.17g}\n",ranks,omp_get_max_threads(),row.size(),(unsigned long long)passed,(unsigned long long)evaluations,(unsigned long long)all_leaves,(unsigned long long)stable,(unsigned long long)poly,(unsigned long long)roots,deepest,sumM,sumK,maxMratio,maxKratio,passed==row.size()?"true":"false",seconds);
    }active_mpi=false;MPI_Finalize();return 0;
}
#endif
